using System;using System.Linq;using System.Text;using System.Globalization;using System.Collections.Generic;
namespace BeamScheduleFormatter {
class ConnectionInput {
 public string Family="Angle",Method="LRFD",Connection="Weld",Grade="A325";public double Area=1000,Thickness=6,Offset=20,Fy=248,Fu=400,GussetFy=248,GussetFu=400,GussetThickness=6,GussetWidth=150,Demand=0,Weld=4,WeldEdgeThickness=0,Fexx=482.65,LT=0,LL1=100,LL2=100,BoltDiameter=16,HoleDiameter=18,EdgeDistance=35,Spacing=50,Fnv=372,VerifiedU=0,Agv=0,Anv=0,Ant=0;public int Bolts=3,ShearPlanes=1;public bool Exposed=true,DirectionalWeldIncrease=false,AllElementsConnected=false,VerifiedProperties=false;
 public void Validate(){if(!new[]{"Angle","Double angle","HSS rectangle","HSS circle / pipe"}.Contains(Family)||!new[]{"Weld","Bolts"}.Contains(Connection)||!new[]{"LRFD","ASD"}.Contains(Method))throw new Exception("Choose family, method and connection.");SteelWeight.Positive(Area,Thickness,Fy,Fu,GussetThickness,GussetFy,GussetFu,GussetWidth);if(Fu<Fy||GussetFu<GussetFy||double.IsNaN(Demand)||double.IsInfinity(Demand)||Demand<0||double.IsNaN(Offset)||double.IsInfinity(Offset)||Offset<0)throw new Exception("Check strength, centroid offset and nonnegative axial demand.");if(VerifiedU<0||VerifiedU>1||double.IsNaN(VerifiedU))throw new Exception("Verified shear-lag U must be 0 (derive) or >0 and <=1.");if(Connection=="Weld"){SteelWeight.Positive(Weld,Fexx);if(double.IsNaN(WeldEdgeThickness)||double.IsInfinity(WeldEdgeThickness)||WeldEdgeThickness<0||WeldEdgeThickness>Math.Max(Thickness,GussetThickness))throw new Exception("Check actual thickness at the welded edge.");foreach(double v in new[]{LT,LL1,LL2})if(double.IsNaN(v)||double.IsInfinity(v)||v<0)throw new Exception("Weld lengths must be finite and nonnegative.");if(LT+LL1+LL2<=0)throw new Exception("Enter at least one weld length.");}else{if(Family.StartsWith("HSS"))throw new Exception("Supplied HSS sheets cover welded connections only; bolted HSS wall checks require a separate detail.");SteelWeight.Count(Bolts);SteelWeight.Positive(BoltDiameter,HoleDiameter,EdgeDistance,Spacing,Fnv);if(!new[]{"A307","A325"}.Contains(Grade)||ShearPlanes<1||ShearPlanes>2||HoleDiameter<=BoltDiameter)throw new Exception("Check bolt grade, shear planes and explicit hole diameter.");}foreach(double v in new[]{Agv,Anv,Ant})if(double.IsNaN(v)||double.IsInfinity(v)||v<0)throw new Exception("Block shear areas must be finite and nonnegative.");if((Agv>0||Anv>0||Ant>0)&&!(Agv>0&&Anv>0&&Ant>0))throw new Exception("Enter all three block-shear areas or leave all zero.");if(Anv>Agv)throw new Exception("Net shear area cannot exceed gross shear area.");}
}
class ConnectionCheck {public string Name,Note;public double Capacity,Demand;public bool Pass{get{return Capacity>=Demand;}}}
class ConnectionResult {public readonly List<ConnectionCheck> Checks=new List<ConnectionCheck>();public readonly List<string> DetailErrors=new List<string>();public double U,NominalWeld,NominalBolt,NominalBearing,NominalRupture;public bool ListedChecksPass{get{return DetailErrors.Count==0&&Checks.All(c=>c.Pass);}}}
static class TrussConnectionDesigner {
 static double Available(double nominal,string method,double phi,double omega){return method=="LRFD"?nominal*phi:nominal/omega;}
 static double WeldLength(double length,double size){double ratio=length/size;return ratio<=100?length:ratio<=300?(1.2-.002*ratio)*length:180*size;}
 public static ConnectionResult Calculate(ConnectionInput input){input.Validate();var r=new ConnectionResult();int legs=input.Family=="Double angle"?2:1;double gross=input.Area*legs,minThickness=Math.Min(input.Thickness,input.GussetThickness);Action<string,double,double,string> add=(name,nominal,phi,note)=>r.Checks.Add(new ConnectionCheck{Name=name,Capacity=Available(nominal,input.Method,phi,phi==.9?1.67:2),Demand=input.Demand,Note=note});add("Member gross tension yielding",input.Fy*gross/1000,.9,"Screened against absolute axial envelope, including compression-only imports conservatively.");
  double length=input.Connection=="Weld"?(input.LL1+input.LL2)/2:(input.Bolts-1)*input.Spacing;if(input.AllElementsConnected)r.U=1;else if(input.VerifiedU>0)r.U=input.VerifiedU;else{if(length<=0)throw new Exception("Supply verified U for a nonstandard/transverse-only or one-bolt connection, or confirm all cross-section elements are connected.");r.U=1-input.Offset/length;if(r.U<=0||r.U>1)throw new Exception("Derived U=1-xbar/L must be >0 and <=1; review connection length/offset.");}
  if(input.Connection=="Weld"){double thicker=Math.Max(input.Thickness,input.GussetThickness),minimum=thicker<=6?3:thicker<=13?5:thicker<=19?6:8,edgeThickness=input.WeldEdgeThickness>0?input.WeldEdgeThickness:input.Thickness,maximum=edgeThickness<6?edgeThickness:edgeThickness-2;if(input.Weld<minimum||input.Weld>maximum)r.DetailErrors.Add("Fillet size outside minimum "+minimum+"mm / edge maximum "+maximum+"mm. Verify actual weld detail and applicable exceptions.");foreach(double segment in new[]{input.LT,input.LL1,input.LL2})if(segment>0&&segment<4*input.Weld)r.DetailErrors.Add("Each effective fillet segment must be at least 4 x weld size.");double longitudinal=.707*input.Weld*(WeldLength(input.LL1,input.Weld)+WeldLength(input.LL2,input.Weld))*.6*input.Fexx/1000,transverse=.707*input.Weld*WeldLength(input.LT,input.Weld)*.6*input.Fexx/1000;r.NominalWeld=(input.DirectionalWeldIncrease?Math.Max(longitudinal+transverse,.85*longitudinal+1.5*transverse):longitudinal+transverse)*legs;add("Fillet weld metal",r.NominalWeld,.75,"0.707w x effective weld length x 0.60Fexx; phi=.75 / Omega=2.00.");r.NominalRupture=input.Fu*r.U*gross/1000;add("Member tensile rupture / shear lag",r.NominalRupture,.75,"U="+r.U.ToString("0.######",CultureInfo.InvariantCulture)+"; area per angle, then assembly multiplicity once.");}
  else{double minSpacing=8.0/3*input.BoltDiameter,maxSpacing=input.Exposed?Math.Min(14*minThickness,180):Math.Min(24*minThickness,300),maxEdge=Math.Min(12*minThickness,150);if(input.Spacing<minSpacing||input.Spacing>maxSpacing)r.DetailErrors.Add("Bolt spacing outside "+minSpacing.ToString("0.###")+" to "+maxSpacing+"mm.");if(input.EdgeDistance<1.75*input.BoltDiameter||input.EdgeDistance>maxEdge)r.DetailErrors.Add("Edge distance outside conservative 1.75db to min(12t,150mm). Confirm edge preparation/table exceptions.");double clear=Math.Min(input.Spacing-input.HoleDiameter,input.EdgeDistance-input.HoleDiameter/2);if(clear<=0)throw new Exception("Hole diameter leaves no clear edge/spacing distance.");r.NominalBolt=input.Fnv*Math.PI*input.BoltDiameter*input.BoltDiameter/4*input.Bolts*input.ShearPlanes/1000;add("Bolt shear",r.NominalBolt,.75,"One shear plane for a single angle; two only for a verified double-shear joint.");double member=input.Bolts*Math.Min(1.2*clear*input.Thickness*input.Fu,2.4*input.BoltDiameter*input.Thickness*input.Fu)*legs/1000,gusset=input.Bolts*Math.Min(1.2*clear*input.GussetThickness*input.GussetFu,2.4*input.BoltDiameter*input.GussetThickness*input.GussetFu)/1000;r.NominalBearing=Math.Min(member,gusset);add("Member bearing",member,.75,"Clear distance=min(s-hole, edge-hole/2); one longitudinal bolt row.");add("Gusset bearing",gusset,.75,"Gusset counted once, even with double angles.");double net=gross-input.HoleDiameter*input.Thickness*legs;if(net<=0)throw new Exception("Bolt hole consumes the net section.");r.NominalRupture=input.Fu*r.U*net/1000;add("Member net tensile rupture",r.NominalRupture,.75,"One hole per angle across net section; no stagger assumed.");double gussetNet=(input.GussetWidth-input.HoleDiameter)*input.GussetThickness;if(gussetNet<=0)throw new Exception("Gusset width must exceed the hole diameter.");add("Gusset gross yielding",input.GussetFy*input.GussetWidth*input.GussetThickness/1000,.9,"Gusset width must represent the effective load-transfer width.");add("Gusset net rupture",input.GussetFu*gussetNet/1000,.75,"One hole across gusset net width; no stagger.");}
  if(input.Agv>0){double nominal=Math.Min(.6*input.Fu*input.Anv+input.Fu*input.Ant,.6*input.Fy*input.Agv+input.Fu*input.Ant)/1000;add("Verified member block-shear path",nominal,.75,"Agv/Anv/Ant are TOTAL assembly path areas; Ubs=1 assumes uniform tensile stress. Check gusset paths separately.");}return r;
 }
 public static string Report(ConnectionInput input,ConnectionResult r,string profile,string source){var b=new StringBuilder();b.AppendLine("TRUSS CONNECTION | "+input.Family+" | "+input.Connection+" | "+input.Method);b.AppendLine(profile+" | "+source);b.AppendLine("AXIAL, CONCENTRIC CONNECTION CHECKS ONLY. Member compression/buckling, combined bending/shear, gusset buckling, complete HSS chord/joint limit states, prying, fatigue and seismic detailing are outside this sheet.");b.AppendLine("Section input basis: "+(input.VerifiedProperties?"user-confirmed verified geometry/properties":"nominal sharp-corner geometry; manufacturer/section verification remains required"));b.AppendLine(string.Format(CultureInfo.InvariantCulture,"Axial demand={0:0.###}kN; area PER angle/member={1:0.###}mm2; t={2:0.###}mm; centroid offset={3:0.###}mm; U={4:0.######}",input.Demand,input.Area,input.Thickness,input.Offset,r.U));b.AppendLine(string.Format(CultureInfo.InvariantCulture,"Member Fy/Fu={0}/{1}MPa; gusset Fy/Fu={2}/{3}MPa; gusset t={4}mm",input.Fy,input.Fu,input.GussetFy,input.GussetFu,input.GussetThickness));foreach(var check in r.Checks)b.AppendLine(string.Format(CultureInfo.InvariantCulture,"{0}: capacity {1:0.###}kN; demand {2:0.###}kN; DCR {3:0.######}; {4}\n  {5}",check.Name,check.Capacity,check.Demand,check.Demand/check.Capacity,check.Pass?"WITHIN":"EXCEEDED",check.Note));foreach(string error in r.DetailErrors)b.AppendLine("DETAIL CHECK: "+error);b.AppendLine(input.Agv>0?"Block shear: only the entered verified MEMBER path is checked; assess all gusset paths separately.":"BLOCK SHEAR NOT CHECKED: provide verified path areas and assess all member/gusset paths before final design.");b.AppendLine(r.ListedChecksPass?"LISTED CHECKS WITHIN LIMITS; connection verification remains incomplete for omitted limit states.":"LISTED CHECKS OR DETAIL LIMITS EXCEEDED.");b.AppendLine("WORKBOOK BASIS / CORRECTIONS");b.AppendLine("Supplied PS Truss workbooks Y135:Y184: fillet strength, shear lag, bolt shear/bearing, member rupture. LRFD/ASD load demand must match the selected method.");b.AppendLine("Fillet phi=.75/Omega=2.00 per AISC 360 Table J2.5, replacing workbook .9/1.67. Min fillet size follows thicker part, max follows the actual welded edge (default member edge); workbook weld-size/thickness lookup is corrected. Standard hole input is distinct from minimum edge distance; clear end distance subtracts half the hole.");b.AppendLine("Double-angle area, weld lines and member bearing are multiplied once; bolt shear uses explicit shear planes; gusset bearing is never doubled. Shear-lag uses centroid offset, not the workbook double-angle radius-of-gyration reference.");b.AppendLine("AISC 360-16: https://www.aisc.org/globalassets/aisc/publications/standards/a360-16-spec-and-commentary_march-2021.pdf");return b.ToString();}
}
}
